<?php

namespace App\Mock\Manifest;

use RuntimeException;

/**
 * Read-only access to resources/manifest.json, generated by `mock:build-manifest` (R7).
 * The runtime never reads the collection itself.
 */
final class Manifest
{
    /** @var array{entries: list<array<string, mixed>>, observedEnums: array<string, list<string>>}|null */
    private ?array $data = null;

    public function __construct(private readonly string $path) {}

    public static function path(): string
    {
        return base_path('resources/manifest.json');
    }

    /** @return list<array<string, mixed>> */
    public function entries(): array
    {
        return $this->data()['entries'];
    }

    /** @return array<string, mixed> */
    public function entry(string $id): array
    {
        foreach ($this->entries() as $entry) {
            if ($entry['id'] === $id) {
                return $entry;
            }
        }
        throw new RuntimeException("No manifest entry '{$id}'.");
    }

    /** @return array<string, array{type: string, functions: list<string>}> */
    public function filterTable(string $id): array
    {
        return $this->entry($id)['filter']['properties'];
    }

    /** @return array{required: list<string>, optional: list<string>, noDescent: bool, map: bool} */
    public function responseFields(string $id, string $path = ''): array
    {
        $fields = $this->entry($id)['response']['fields'][$path] ?? null;
        if ($fields === null) {
            throw new RuntimeException("Manifest entry '{$id}' has no response object at '{$path}'.");
        }

        return $fields;
    }

    /** @return array<string, array<string, mixed>> */
    public function requestFields(string $id): array
    {
        return $this->entry($id)['request']['fields'] ?? [];
    }

    /** @return array<string, list<string>> */
    public function observedEnums(): array
    {
        return $this->data()['observedEnums'];
    }

    private function data(): array
    {
        if ($this->data === null) {
            if (! is_file($this->path)) {
                throw new RuntimeException("Manifest not found at {$this->path}; run php artisan mock:build-manifest.");
            }
            $this->data = json_decode(file_get_contents($this->path), true, flags: JSON_THROW_ON_ERROR);
        }

        return $this->data;
    }
}
